import { PublicKey } from '@solana/web3.js'
import type { IdlAccounts, IdlTypes } from '@anchor-lang/core'

import type { SetupResult } from '../../config/index.ts'
import { derivePda, tokenPoolSeeds } from '../decode-pda.ts'
import { getMultipleAccountsBatched } from '../../utils/batched-rpc.ts'

// Type sources: the 2.0 typed bindings (auto-generated by Anchor 1.0) inline
// all cross-IDL `defined:` references (BaseConfig, BaseChain, etc.), so they
// give us complete structural types. On-chain shapes are aligned between 1.6
// and 2.0 for everything we touch — these types are accurate for both versions.
import type { BurnmintTokenPool } from '../../../../contracts/target/types/burnmint_token_pool.ts'
import type { CcipRouter } from '../../../../contracts/target/types/ccip_router.ts'

export type PoolProgramKey = 'burnmintTokenPool' | 'lockReleaseTokenPool' | 'cctpTokenPool'

/**
 * Given the on-chain owner of a token-pool State PDA, return the matching configured-program
 * key (so we know which Anchor coder to use). Falls back to `burnmintTokenPool` for custom
 * pools — their State layout is dictated by base_token_pool which is shared.
 */
export function pickPoolProgramKey(ctx: SetupResult, programId: PublicKey): PoolProgramKey {
  const bag: Record<string, any> = (ctx.ccipVersion === '2.0' ? ctx.programs : ctx.legacyPrograms) as any
  for (const k of ['burnmintTokenPool', 'lockReleaseTokenPool', 'cctpTokenPool'] as const) {
    const p = bag[k]
    if (p?.programId?.equals?.(programId)) return k
  }
  return 'burnmintTokenPool'
}

// Common typed shapes used by multiple commands — extracted from the 2.0
// typed bindings via Anchor's `IdlAccounts<>`/`IdlTypes<>` helpers.

export type PoolState = IdlAccounts<BurnmintTokenPool>['state']
export type TokenAdminRegistry = IdlAccounts<CcipRouter>['tokenAdminRegistry']

/**
 * Decode whether ALT entry `index` is marked writable in `writableIndexes`.
 * Layout per chainlink-ccip ccip-common/src/v1.rs:`token_admin_registry_writable`:
 *   - index 0..127  → bit (127 - index) of writableIndexes[0]
 *   - index 128..255 → bit (255 - index) of writableIndexes[1]
 */
export function isWritableEntry(writableIndexes: any[], index: number): boolean {
  const word = index < 128 ? writableIndexes[0] : writableIndexes[1]
  const bit = BigInt(index < 128 ? 127 - index : 255 - index)
  const w = typeof word === 'bigint' ? word : BigInt(word.toString())
  return (w >> bit) & 1n ? true : false
}

export type ChainConfig = IdlAccounts<BurnmintTokenPool>['chainConfig']

/** Render a Unix timestamp from a u64 (Anchor 0.29 → BN, Anchor 1.0 → bigint). */
export function fmtTimestamp(
  ts: bigint | number | { toNumber(): number } | { toString(): string }
): string {
  const n =
    typeof ts === 'bigint'
      ? Number(ts)
      : typeof ts === 'number'
        ? ts
        : typeof (ts as any).toNumber === 'function'
          ? (ts as any).toNumber()
          : Number(ts.toString())
  if (!n) return 'never'
  return new Date(n * 1000).toISOString().replace('T', ' ').replace('.000Z', ' UTC')
}

/**
 * Derive a ChainConfig PDA for each candidate selector, batch-fetch, and
 * decode the ones that exist. Avoids a program-wide `getProgramAccounts`
 * scan and recovers the selector (which the on-chain account doesn't
 * store — it lives only in the PDA seed).
 */
export async function fetchChainConfigs(
  ctx: SetupResult,
  programKey: PoolProgramKey,
  mint: PublicKey,
  selectors: bigint[]
): Promise<Array<{ selector: bigint; pda: PublicKey; config: ChainConfig }>> {
  const pdas = selectors.map((sel) => derivePda(ctx, programKey, tokenPoolSeeds.chainConfig(sel, mint)))
  const infos = await getMultipleAccountsBatched(ctx.provider.connection, pdas)
  const coder = (ctx.ccipVersion === '2.0' ? ctx.programs : ctx.legacyPrograms)[programKey]!.coder
    .accounts
  const out: Array<{ selector: bigint; pda: PublicKey; config: ChainConfig }> = []
  for (let i = 0; i < selectors.length; i++) {
    const acct = infos[i]
    if (!acct) continue
    try {
      const config = coder.decode('chainConfig', acct.data) as ChainConfig
      out.push({ selector: selectors[i], pda: pdas[i], config })
    } catch {
      /* old layout — skip */
    }
  }
  return out
}
